public static int lastValue(Node<Integer> first) {
    Node<Integer> p = first;
    while (p.getNext() != null) {
        p = p.getNext();
    }
    return p.getValue();
}

public static boolean isSorted(Node<Integer> first) {
    Node<Integer> p = first;
    while (p.getNext() != null) {
        if (p.getNext().getValue() < p.getValue()) {
            return false;
        }
        p = p.getNext();
    }
    return true;
}

exercise.mainCode:
Node<Integer> a = new Node<Integer>(2, new Node<Integer>(5, new Node<Integer>(5, new Node<Integer>(9))));
Node<Integer> b = new Node<Integer>(3, new Node<Integer>(8, new Node<Integer>(6)));
System.out.println("סעיף א: " + lastValue(a) + " " + lastValue(b));
System.out.println("סעיף ב: " + isSorted(a) + " " + isSorted(b));
